{"rules": [
 {
  "title": "Suspicious process from web service",
  "level": "high",
  "logsource": {
   "category": "process_creation"
  },
  "detection": {
   "web_parent": {
    "parent_process|contains": "httpd"
   },
   "shell": {
    "process_name|contains": "sh"
   },
   "condition": "web_parent AND shell"
  },
  "confidence": 0.85,
  "rationale": "Web servers spawning shells is a strong indicator of remote code execution or web shell activity."
 },
 {
  "title": "Direct connection to decoy subnet",
  "level": "high",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "decoy_subnet": {
    "is_decoy": true
   },
   "condition": "decoy_subnet"
  },
  "confidence": 0.95,
  "rationale": "Any network traffic directed at a decoy asset is highly suspicious and indicates lateral movement or scanning."
 },
 {
  "title": "Privileged service modification",
  "level": "medium",
  "logsource": {
   "category": "service_event"
  },
  "detection": {
   "high_priv": {
    "privilege": "elevated"
   },
   "service_change": {
    "service_name|contains": "svc"
   },
   "condition": "high_priv AND service_change"
  },
  "confidence": 0.6,
  "rationale": "Changes to system services with elevated privileges can indicate persistence mechanisms."
 },
 {
  "title": "Unexpected outbound connection from server",
  "level": "medium",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "server_zone": {
    "zone": "server"
   },
   "external_ip": {
    "dst_ip|startswith": "10."
   },
   "condition": "server_zone AND NOT external_ip"
  },
  "confidence": 0.5,
  "rationale": "Servers in this zone should primarily communicate within the internal subnet; unexpected external IPs may indicate C2."
 },
 {
  "title": "Non-standard port usage by system process",
  "level": "low",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "system_proc": {
    "process_name|contains": "system"
   },
   "weird_port": {
    "dst_port": [
     4444,
     6667,
     8080
    ]
   },
   "condition": "system_proc AND weird_port"
  },
  "confidence": 0.4,
  "rationale": "System processes communicating on non-standard ports can be a sign of tunneling or reverse shells."
 }
]}

{"rules": [
 {
  "title": "Unauthorized access to restricted zone",
  "level": "high",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "restricted_subnet": {
    "subnet": "restricted_zone_a"
   },
   "green_user": {
    "src_ip|contains": "green"
   },
