 },
 {
  "title": "Unexpected process from network service",
  "level": "high",
  "logsource": {
   "category": "process_creation"
  },
  "detection": {
   "service_parent": {
    "parent_process|contains": "service"
   },
   "suspicious_proc": {
    "process_name": ["cmd.exe", "sh", "bash", "powershell"]
   },
   "condition": "service_parent AND suspicious_proc"
  },
  "confidence": 0.8,
  "rationale": "Network services spawning interactive shells is a strong indicator of exploitation."
 },
 {
  "title": "Direct connection to decoy host",
  "level": "high",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "decoy_hit": {
    "is_decoy": true
   },
   "condition": "decoy_hit"
  },
  "confidence": 0.95,
  "rationale": "Any interaction with a decoy host is highly suspicious and likely reconnaissance."
 },
 {
  "title": "Privileged process execution in server zone",
  "level": "medium",
  "logsource": {
   "category": "process_creation"
  },
  "detection": {
   "high_priv": {
    "privilege": "elevated"
   },
   "server_host": {
    "host_id|contains": "server"
   },
   "condition": "high_priv AND server_host"
  },
  "confidence": 0.6,
  "rationale": "Monitoring for elevated processes on server hosts to detect potential privilege escalation."
 }
]}

